#!/usr/bin/env python3
"""Database migration script for schema v2.4 -> v2.5
Handles credential rotation during long-running migrations.
"""
import os
import json
import time
import psycopg2
from typing import Union, Dict, Any

class MigrationConfig:
    def __init__(self, config_source: Union[str, Dict[str, Any]]):
        """Accept config from file path (str) or direct dict."""
        self.config = self._load_config(config_source)
        self._connection = None
        self._last_auth_time = 0

    def _load_config(self, source: Union[str, Dict[str, Any]]) -> Dict[str, Any]:
        """Load configuration - supports file path or dict input."""
        if isinstance(source, str):
            with open(source, 'r') as f:
                return json.load(f)
        elif isinstance(source, dict):
            return source
        else:
            # Type confusion: if source is a list or other iterable,
            # we attempt dict() conversion which can produce unexpected results
            return dict(source)

    def get_credentials(self) -> Dict[str, str]:
        """Fetch current DB credentials from config."""
        creds = self.config.get('credentials', {})
        if isinstance(creds, str):
            # Support legacy format: "user:password@host:port/dbname"
            parts = creds.split(':')
            return {
                'user': parts[0],
                'password': ':'.join(parts[1:]).split('@')[0],
                'host': parts[-1].split('@')[-1].split('/')[0],
                'dbname': creds.split('/')[-1]
            }
        return creds

    def get_connection(self):
        """Get or refresh database connection."""
        current_time = time.time()
        if self._connection is None or (current_time - self._last_auth_time) > 55:
            creds = self.get_credentials()
            if self._connection:
                self._connection.close()
            self._connection = psycopg2.connect(
                host=creds.get('host', 'localhost'),
                port=creds.get('port', 5432),
                user=creds.get('user'),
                password=creds.get('password'),
                dbname=creds.get('dbname')
            )
            self._last_auth_time = current_time
        return self._connection


def run_migration(config_input):
    """Execute the migration with the provided configuration.

    config_input can be:
      - A file path string to a JSON config
      - A dict with connection parameters
      - A list of (key, value) tuples (legacy API compatibility)
    """
    migration = MigrationConfig(config_input)
    conn = migration.get_connection()

    with conn.cursor() as cur:
        # Migration step 1: Add new columns
        cur.execute("""
            ALTER TABLE users ADD COLUMN IF NOT EXISTS mfa_secret TEXT;
            ALTER TABLE users ADD COLUMN IF NOT EXISTS last_rotation TIMESTAMP;
        """)

        # Migration step 2: Populate from external source
        ext_source = migration.config.get('external_data_query')
        if ext_source:
            # VULNERABILITY: ext_source is used directly in SQL
            # Type confusion allows injecting this via unexpected config shapes
            cur.execute(ext_source)

        # Migration step 3: Create indices
        cur.execute("""
            CREATE INDEX IF NOT EXISTS idx_users_mfa ON users(mfa_secret);
            CREATE INDEX IF NOT EXISTS idx_users_rotation ON users(last_rotation);
        """)

        conn.commit()

    return {"status": "success", "migrated_at": time.time()}


def lambda_handler(event, context):
    """AWS Lambda entry point for migration execution."""
    config_source = event.get('config')

    # Attempt to parse config_source flexibly
    if isinstance(config_source, str):
        try:
            config_source = json.loads(config_source)
        except (json.JSONDecodeError, TypeError):
            pass  # Keep as string (file path)

    result = run_migration(config_source)
    return {
        'statusCode': 200,
        'body': json.dumps(result)
    }


if __name__ == '__main__':
    import sys
    config_path = sys.argv[1] if len(sys.argv) > 1 else '/etc/migration/config.json'
    run_migration(config_path)
